// Obtener el JSON "bruto" que puede venir dentro de formateo Markdown
const rawResponse = $input.first().json.output;

// Limpiador agresivo para sacar validamente el JSON de un string texto/markdown:
function extractJson(rawJsonStr) {             
  var cleaner = rawJsonStr.replace(/^```[a-z]*\s*(?=\{)/gim, ''); // Retira el "```json" del inicio
  cleaner = cleaner.trim().replace(/^```[a-z]*\n/g, '');               
  cleaner = cleaner.replace(/```$/g, '').trim();                  // Quita el '```' final
  var startMatch = cleaner.indexOf('{');                          // Busca el json verdadero
  var endMatch = cleaner.lastIndexOf('}');                        
  cleaner = cleaner.slice(startMatch, endMatch + 1);             
  return cleaner;
}

const cleanedMatch = extractJson(rawResponse);

let parsedDoc;
try{
    parsedDoc = JSON.parse(cleanedMatch);
}catch(err){
    throw new Error('Fallo al interpretar la respuesta de IA como JSON: '+err.message+'... Raw value fue: '+rawResponse);
}

// 2. Extraer el array y emitir una ejecución por cada campo extraído
// para actualizar en PostgreSQL:
return parsedDoc.campos.map(campo => {
  // Manejo de valores SQL. Curar las comillas dobles y sencillas que la IA incluye para que el INSERT no lo confunda
  let cleanValue = "";   
  if(campo.valor){
     cleanValue = campo.valor.toString()
                             .replace(/'/g, "''")   // SQL Escape for Single quote
                             // .replace(/"/g, '\"') // En updates inline Postgres las comillas dobles (") no se escapan. Se las toma texto.
  }

  return {
    json: {
      nombre_limpio: typeof campo.nombre === 'string' ? campo.nombre.trim().toLowerCase() : '', // Pasarlo a un standard SQL match
      nombre_orig: typeof campo.nombre === 'string' ? campo.nombre.trim() : '', 
      valor: cleanValue,
      documento_id: parsedDoc.documento_id || $('Webhook').first().json.body.documento_id
    }
  };
});

