const body = $input.item.json.body;
const cadena = body.cadena_oficios;

let texto_para_ia = `Instrucciones: Eres un asistente experto en analizar requerimientos legales y técnicos. Vas a analizar una cadena de ${cadena.length} documentos y generar un resumen ejecutivo, identificar pendientes, e identificar el estado global. \n\n`;

texto_para_ia += `======= CADENA DE OFICIOS =======\n\n`;

for(let i=0; i<cadena.length; i++) {
    const doc = cadena[i];
    texto_para_ia += `--- DOCUMENTO ${i+1}: ${doc.codigo} ---\n`;
    texto_para_ia += `Título: ${doc.titulo}\n`;
    texto_para_ia += `Fecha: ${doc.fecha_emision}\n`;
    texto_para_ia += `Metadatos: ${JSON.stringify(doc.metadatos)}\n`;
    texto_para_ia += `Texto Extraído:\n${doc.texto_extraido}\n\n`;
}

return {
    texto_redactado: texto_para_ia
};

